<script setup>import AppShell from '@/Components/AppShell.vue';import{Link}from'@inertiajs/vue3';const p=defineProps({submission:Object});const doc=id=>'/documents/'+id;const all='/submissions/'+p.submission.id+'/documents/download-all';</script>
<template><AppShell title="Detail Pengajuan" :subtitle="submission.submission_number" eyebrow="Akun Vendor"><div class="mb-4 flex flex-wrap justify-between gap-3"><Link href="/vendor" class="btn-ghost">← Kembali</Link><a :href="all" class="btn">↓ Download Semua Dokumen</a></div><div class="panel"><h2 class="text-2xl font-black">{{submission.vendor_name}}</h2><p class="mt-1 text-sm text-slate-500">{{submission.applicant_name}} · {{submission.phone}}</p><span class="status-badge mt-4" :class="'status-'+submission.status.toLowerCase()">{{submission.status}}</span><p class="mt-4 rounded-xl bg-slate-50 p-4 text-sm text-slate-600">{{submission.coordinator_note||'Belum ada catatan koordinator.'}}</p><div class="mt-6 grid gap-3 md:grid-cols-2"><a v-for="d in submission.documents" :href="doc(d.id)" target="_blank" class="rounded-xl border border-slate-200 p-4 transition hover:border-red-200 hover:bg-red-50"><b>{{d.document_name}}</b><p class="mt-1 text-xs text-slate-500">{{(d.file_size/1048576).toFixed(2)}} MB · Lihat PDF</p></a></div></div></AppShell></template>
